    },
    {
      "role": "agent",
      "responsibility": "按所需工具/网络和隔离边界执行具体构建测试",
      "known_export": "numExecutors=1, mode=EXCLUSIVE, label empty, SSHLauncher",
      "not_proven": "未证连接、可用工具/标签或构建成功；设计前需核任务agent匹配，不改实际节点"
    },
    {
      "role": "plugins",
      "responsibility": "提供SCM、Pipeline、报告/凭据等集成能力",
      "known_export": "14个flow-definition；13个CpsFlowDefinition，1个CpsScmFlowDefinition",
      "not_proven": "XML引用的插件标识不是已加载版本或兼容验收"
    }
  ],
  "stages": [
    {
      "stage": "checkout",
      "input": "已授权事件与精确revision",
      "output": "检出revision及来源记录",
      "gate": "事件/仓库/身份不匹配停止"
