  "pipeline_environment": {
    "controller": "负责授权事件验证、调度和报告；日常测试计划在受限agent执行",
    "agent": "指定组织批准的JDK/Wrapper与依赖来源，不读取生产凭据；每run独立workspace/cache边界",
    "version_evidence": "记录实际core/plugins/JDK/Wrapper版本与锁定/校验来源后才允许原生验证",
    "current_agent_export_limit": "1executor EXCLUSIVE空label是配置，不自动满足所需环境或调度"
  },
  "stages": [
    {
      "order": 1,
      "name": "event_and_trust",
      "action": "核仓库、事件签名/既有认证、分支/PR信任和精确revision，不仅取某个浮动分支末端",
      "output": "事件到revision及触发身份记录",
      "gate": "不匹配停止；T2不分配发布身份"
    },
    {
      "order": 2,
      "name": "checkout_and_workspace",
      "action": "在每run隔离目录检出准确revision，记录源码引用和工作区/并发归属",
      "output": "revision与输入清单；不继承上次成功残留",
      "gate": "检出失败/来源变更停止"
    },
    {
      "order": 3,
      "name": "locked_environment",
      "action": "核受审Wrapper/JDK/依赖锁定或校验策略，准备受限测试环境",
      "output": "实际版本与依赖来源/摘要证据",
      "gate": "未知版本或不匹配锁定策略阻断；不把本机缓存命中当来源证明"
    },
    {
      "order": 4,
      "name": "unit_test",
      "action": "设计命令示例./mvnw -B -ntp test；使用仓库已评审的等价命令也可，当前未执行",
      "output": "精确命令/退出码/stdout/stderr及JUnit XML等报告",
      "gate": "非零、超时、缺失/无法解析必需报告不变绿；T3保存失败证据"
    },
    {
      "order": 5,
      "name": "publish_feedback",
      "action": "无论成功失败均在批准保留范围保存报告/失败日志和revision/run链接，反馈检查状态",
      "output": "可追踪报告、失败原因与保留/清理记录",
      "gate": "报告发布不覆盖原测试退出码；敏感信息脱敏"
    },
    {
      "order": 6,
      "name": "downstream_boundary",
      "action": "仅经门禁通过的受信revision可进入另行批准的制品/发布流程",
      "output": "明确success/failed/cancelled状态及下游停止决定",
      "gate": "PR、失败、超时或不完整证据不得取得生产凭据或发布"
    }
  ],
  "case_decisions": {
    "T1": "必须触发同revision反馈，环境和报告门未证实时不能宣称通过",
    "T2": "运行无秘密受限测试，不能继承发布身份",
    "T3": "失败或证据不完整，保留日志并阻断后续发布"
  },
  "execution_status": "design_not_executed_no_webhook_or_build_triggered"
}

